(() => {
  const clean = (s) => (s || '').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const all = [...document.querySelectorAll('input,textarea')].filter(vis);
  const 问 = [];
  const 公司 = all.find((x) => (x.placeholder || '').includes('北京华品博睿'));
  const 职位 = all.find((x) => (x.placeholder || '').includes('选择职位名称'));
  const 时间 = all.filter((x) => (x.placeholder || '').includes('选择在职时间'));
  const 内容 = all.filter((x) => x.tagName === 'TEXTAREA')[0];
  const 勾 = [...document.querySelectorAll('input[type=checkbox]')].find((x) => (((x.closest('div[class*=form-item]') || x.parentElement || {}).innerText) || '').includes('实习经历'));
  if (!公司 || clean(公司.value) !== '天鹅到家') 问.push('公司=' + (公司 ? clean(公司.value) : '没有这个框'));
  if (!职位 || !clean(职位.value)) 问.push('职位名=空');
  if (时间.length < 2 || !clean(时间[0].value) || !clean(时间[1].value)) 问.push('时间=' + 时间.map((x) => clean(x.value)).join('~'));
  if (!内容 || 内容.value.length < 100) 问.push('工作内容=' + (内容 ? 内容.value.length : 0) + '字');
  if (!勾 || !勾.checked) 问.push('实习经历没勾');
  if (问.length) return '不保存，缺：' + 问.join('；') + '｜已读到：职位=' + (职位 ? clean(职位.value) : '') + ' 时间=' + 时间.map((x) => clean(x.value)).join('~');
  const ok = document.querySelector('[ka=resume_form_work_ok]');
  if (!ok) return '全对但没找到完成按钮';
  ok.click();
  return '闸门全过，已点完成：' + clean(公司.value) + ' / ' + clean(职位.value) + ' / ' + clean(时间[0].value) + '-' + clean(时间[1].value) + ' / 正文' + 内容.value.length + '字 / 实习已勾';
})()

(() => {
